import numpy as np
# demo2 points per segment local
p1={(5,4),(5,6),(6,0),(6,5),(6,7),(6,9),(7,5),(9,5),(9,9)}
p2={(1,2),(1,5),(4,5),(5,2),(6,0),(6,7),(6,9),(7,5),(8,2),(9,1),(9,3)}
def comps(points, diag=True):
  pts=set(points); out=[]
  while pts:
    s={pts.pop()}; stack=list(s)
    while stack:
      r,c=stack.pop()
      near=[(r+dr,c+dc) for dr in [-1,0,1] for dc in [-1,0,1] if (dr or dc) and (diag or dr==0 or dc==0)]
      for q in near:
        if q in pts: pts.remove(q); s.add(q); stack.append(q)
    out.append(s)
  return out
for p in [p1,p2]: print([sorted(x) for x in comps(p)])
